window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f866a6adce35a603"]={"versions": [{"id": "FIG-f866a6adce35a603", "releases": ["R2.1.20", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus dem AUTOSAR-Metamodell-Kontext (Template Modeling Guide). Das Diagramm illustriert beispielhaft die elementare Definition und Repräsentation einer Metamodell-Klasse mit Stereotyp und Attributen gemäß den AUTOSAR-Modellierungsrichtlinien.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist die einzelne Metaklasse <code>VehicleModel</code>, annotiert mit dem Stereotyp <code>«atpType»</code>. Die Klasse verfügt über zwei öffentliche Attribute:</p>\n<ul class=\"fig-list\">\n<li><code>articleNo: Int</code> (Artikelnummer vom Typ Integer)</li>\n<li><code>modelName: String</code> (Modellbezeichnung vom Typ String)</li>\n</ul>\n<p class=\"fig-p\">Es sind keine Assoziationen, Vererbungsbeziehungen oder Methoden abgebildet.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm ohne dynamische Interaktionen, Nachrichtenaustausche oder Zustandsübergänge.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Dient als didaktisches Musterbeispiel für die Modellierung von Metaklassen im AUTOSAR Template Modeling Guide. Entwickler und Metamodellierer müssen bei der Definition von Metaklassen das AUTOSAR-Template-Profil anwenden (hier exemplarisch <code>«atpType»</code>) sowie konsistente Namenskonventionen und fundamentale Datentypen für Metaklassen-Attribute beachten.</p>"}, {"id": "FIG-6073fe8c88e8fd0c", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus dem AUTOSAR-Metamodell-Kontext (Template Modeling Guide). Das Diagramm illustriert beispielhaft die elementare Definition und Repräsentation einer Metamodell-Klasse mit Stereotyp und Attributen gemäß den AUTOSAR-Modellierungsrichtlinien.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist die einzelne Metaklasse <code>VehicleModel</code>, annotiert mit dem Stereotyp <code>«atpType»</code>. Die Klasse verfügt über zwei öffentliche Attribute:</p>\n<ul class=\"fig-list\">\n<li><code>articleNo: Int</code> (Artikelnummer vom Typ Integer)</li>\n<li><code>modelName: String</code> (Modellbezeichnung vom Typ String)</li>\n</ul>\n<p class=\"fig-p\">Es sind keine Assoziationen, Vererbungsbeziehungen oder Methoden abgebildet.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm ohne dynamische Interaktionen, Nachrichtenaustausche oder Zustandsübergänge.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Dient als didaktisches Musterbeispiel für die Modellierung von Metaklassen im AUTOSAR Template Modeling Guide. Entwickler und Metamodellierer müssen bei der Definition von Metaklassen das AUTOSAR-Template-Profil anwenden (hier exemplarisch <code>«atpType»</code>) sowie konsistente Namenskonventionen und fundamentale Datentypen für Metaklassen-Attribute beachten.</p>"}, {"id": "FIG-898effa058464458", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus dem AUTOSAR-Metamodell-Kontext (Template Modeling Guide). Das Diagramm illustriert beispielhaft die elementare Definition und Repräsentation einer Metamodell-Klasse mit Stereotyp und Attributen gemäß den AUTOSAR-Modellierungsrichtlinien.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist die einzelne Metaklasse <code>VehicleModel</code>, annotiert mit dem Stereotyp <code>«atpType»</code>. Die Klasse verfügt über zwei öffentliche Attribute:</p>\n<ul class=\"fig-list\">\n<li><code>articleNo: Int</code> (Artikelnummer vom Typ Integer)</li>\n<li><code>modelName: String</code> (Modellbezeichnung vom Typ String)</li>\n</ul>\n<p class=\"fig-p\">Es sind keine Assoziationen, Vererbungsbeziehungen oder Methoden abgebildet.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm ohne dynamische Interaktionen, Nachrichtenaustausche oder Zustandsübergänge.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Dient als didaktisches Musterbeispiel für die Modellierung von Metaklassen im AUTOSAR Template Modeling Guide. Entwickler und Metamodellierer müssen bei der Definition von Metaklassen das AUTOSAR-Template-Profil anwenden (hier exemplarisch <code>«atpType»</code>) sowie konsistente Namenskonventionen und fundamentale Datentypen für Metaklassen-Attribute beachten.</p>"}], "trans": [{"from": "FIG-f866a6adce35a603", "to": "FIG-6073fe8c88e8fd0c", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-6073fe8c88e8fd0c", "to": "FIG-898effa058464458", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-898effa058464458", "to": "FIG-f866a6adce35a603", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
